<script setup lang="ts">
const route = useRoute()
const { data, pending, error } = await useFetch<{ success: boolean; data: any }>(() => `/api/portfolio/${route.params.id}`)
const item = computed(() => data.value?.data)
const selectedEntrySlug = computed(() => String(route.query.entry || ''))
const entryData = ref<any>(null)
watch(selectedEntrySlug, async (slug) => { entryData.value = slug ? await $fetch(`/api/portfolio/${route.params.id}/prompt-entries/${slug}`).catch(() => null) : null }, { immediate: true })
const selectedEntry = computed(() => entryData.value?.data)
const lightbox = ref<any>(null)
const failedMedia = ref(new Set<number>())
const copiedPrompt = ref(false)
const copiedCode = ref(false)
const toolQuery = reactive({ q: String(route.query.q || ''), category: String(route.query.category || ''), page: Number(route.query.page) || 1 })
const toolUrl = computed(() => `/api/portfolio/${route.params.id}/prompt-entries?q=${encodeURIComponent(toolQuery.q)}&category=${encodeURIComponent(toolQuery.category)}&page=${toolQuery.page}`)
const { data: toolData } = await useFetch(toolUrl, { watch: [toolUrl], immediate: true })
const toolEntries = computed(() => Array.isArray(toolData.value?.data?.items) ? toolData.value.data.items : (Array.isArray(item.value?.promptVault?.entries) ? item.value.promptVault.entries : []))
function updateToolQuery() { navigateTo({ query: { ...route.query, q: toolQuery.q || undefined, category: toolQuery.category || undefined, page: toolQuery.page > 1 ? toolQuery.page : undefined } }) }
const media = computed(() => Array.isArray(item.value?.media) ? item.value.media : [])
const blocks = computed(() => Array.isArray(item.value?.blocks) ? item.value.blocks : [])
const toc = computed(() => blocks.value.filter((block: any) => block.anchor && block.title).map((block: any) => ({ anchor: block.anchor, title: block.title })))
const typeLabel = computed(() => ({ project: 'PROJECT / 实验', visual: 'VISUAL / 影像', tool: 'TOOL / 工具' }[item.value?.type] || '作品记录'))
useHead({ title: computed(() => item.value?.title ? `${item.value.title} · 作品` : '作品详情') })
function payload(block: any) { return block?.payload || {} }
function mediaById(id: number | string) { return media.value.find((asset: any) => String(asset.id) === String(id)) }
function copyText(text: string) { navigator.clipboard?.writeText(text) }
async function copyCode(text: string) { await copyText(text); copiedCode.value = true; window.setTimeout(() => { copiedCode.value = false }, 1800) }
async function copyPrompt(text: string) { await copyText(text); copiedPrompt.value = true; window.setTimeout(() => { copiedPrompt.value = false }, 1800) }
function onKeydown(event: KeyboardEvent) { if (event.key === 'Escape') lightbox.value = null }
function mediaFailed(id: number) { failedMedia.value = new Set(failedMedia.value).add(id) }
onMounted(() => window.addEventListener('keydown', onKeydown))
onBeforeUnmount(() => window.removeEventListener('keydown', onKeydown))
</script>

<template>
  <main class="detail-shell">
    <div v-if="pending" class="loading"><div class="skeleton" /><div class="skeleton short" /></div>
    <section v-else-if="error || !item" class="empty"><p>WORK NOT FOUND</p><NuxtLink to="/portfolio">返回作品列表</NuxtLink></section>
    <article v-else :class="['detail', `detail-${item.type}`]">
      <NuxtLink to="/portfolio" class="back">← 返回作品档案</NuxtLink>
      <header class="hero">
         <div><p class="eyebrow">{{ typeLabel }}</p><h1>{{ item.title }}</h1><p class="lede">{{ item.description }}</p><figure v-if="item.type === 'project' && media[0]" class="hero-media"><img :src="media[0].url" :alt="media[0].alt || item.title" /></figure></div>
        <aside class="facts"><span>{{ item.facts?.period || '—' }}</span><span>{{ item.facts?.location || 'Remote archive' }}</span><span v-for="role in (item.facts?.roles || [])" :key="role">{{ role }}</span></aside>
      </header>
       <nav v-if="item.resources?.length" id="resources" class="resource-nav" aria-label="作品资源"><p class="eyebrow">RESOURCES</p><a v-for="resource in item.resources" :key="resource.id" :href="resource.url" target="_blank" rel="noopener">{{ resource.label }} ↗</a></nav>
      <section v-if="media.length && item.type !== 'tool'" class="media-grid" :class="`media-${item.type}`">
        <figure v-for="asset in media" :key="asset.id" class="media-card">
          <video v-if="item.type === 'visual' && asset.kind === 'video' && !failedMedia.has(asset.id)" controls preload="metadata" :poster="asset.poster || undefined" :src="asset.url" :aria-label="asset.alt" @error="mediaFailed(asset.id)" />
          <img v-else-if="asset.kind !== 'video' && !failedMedia.has(asset.id)" :src="asset.url" :alt="asset.alt || item.title" loading="lazy" @error="mediaFailed(asset.id)" @click="lightbox = asset" />
          <div v-else-if="failedMedia.has(asset.id)" class="media-fallback"><p>{{ asset.alt || '媒体暂时无法加载' }}</p><a :href="asset.url" target="_blank" rel="noopener">打开资源 ↗</a></div>
          <figcaption v-if="asset.caption || item.type === 'visual'"><span v-if="item.type === 'visual'">{{ String(media.indexOf(asset) + 1).padStart(2, '0') }} · </span>{{ asset.caption || '影像章节' }}<em v-if="asset.duration">{{ Math.floor(asset.duration / 60) }}:{{ String(asset.duration % 60).padStart(2, '0') }}</em></figcaption>
        </figure>
       </section>
       <section v-if="item.type === 'visual'" class="visual-info-band" aria-label="影像作品信息"><div><span>年份</span><b>{{ item.facts?.period || item.year || '—' }}</b></div><div><span>媒介</span><b>{{ item.facts?.medium || '影像 / 摄影' }}</b></div><div><span>地点</span><b>{{ item.facts?.location || '—' }}</b></div><div><span>时长</span><b>{{ media.find((asset: any) => asset.duration)?.duration ? `${Math.floor(media.find((asset: any) => asset.duration).duration / 60)}:${String(media.find((asset: any) => asset.duration).duration % 60).padStart(2, '0')}` : '—' }}</b></div></section>
       <section v-if="item.type === 'tool' && item.promptVault" id="prompts" class="tool-vault">
         <div class="section-head"><p class="eyebrow">PROMPT VAULT</p><span>{{ item.promptVault.count }} entries</span></div>
         <nav class="tool-tabs" aria-label="工具内容导航"><a href="#overview">项目介绍</a><a class="active" href="#prompts">提示词</a><a href="#resources">资源</a></nav><aside class="tool-side" aria-label="工具功能导航"><strong>功能导航</strong><a class="active" href="#prompts">提示词库</a><a href="#prompts">分类与标签</a><a href="#resources">资源预览</a></aside><aside v-if="item.resources?.length" class="resource-preview"><strong>资源预览</strong><a v-for="resource in item.resources.slice(0, 3)" :key="resource.id" :href="resource.url" target="_blank" rel="noopener"><span>{{ resource.label }}</span><b>↗</b></a></aside>
         <div class="tool-controls"><input v-model="toolQuery.q" placeholder="搜索提示词…" @keyup.enter="updateToolQuery" /><select v-model="toolQuery.category" @change="updateToolQuery"><option value="">全部分类</option><option v-for="category in item.promptVault.categories" :key="category" :value="category">{{ category }}</option></select></div>
        <details v-for="entry in toolEntries" :key="entry.id" class="prompt-entry"><summary><strong>{{ entry.title }}</strong><small>{{ entry.summary }}</small></summary><NuxtLink :to="`/portfolio/${item.slug}?entry=${entry.slug}`">展开条目 →</NuxtLink></details>
        <div v-if="toolData?.data?.pagination?.totalPages > 1" class="tool-pages"><button type="button" :disabled="toolQuery.page <= 1" @click="toolQuery.page--; updateToolQuery()">上一页</button><span>{{ toolData.data.pagination.page }} / {{ toolData.data.pagination.totalPages }}</span><button type="button" :disabled="toolQuery.page >= toolData.data.pagination.totalPages" @click="toolQuery.page++; updateToolQuery()">下一页</button></div>
        <article v-if="selectedEntry" class="selected-entry"><p class="eyebrow">{{ selectedEntry.category || 'PROMPT ENTRY' }}</p><h2>{{ selectedEntry.title }}</h2><p>{{ selectedEntry.summary }}</p><pre>{{ selectedEntry.body }}</pre><button type="button" @click="copyPrompt(selectedEntry.body)">{{ copiedPrompt ? '已复制' : '复制提示词' }}</button><span class="sr-only" aria-live="polite">{{ copiedPrompt ? '已复制' : '' }}</span><details v-if="selectedEntry.variables"><summary>变量说明</summary><pre>{{ JSON.stringify(selectedEntry.variables, null, 2) }}</pre></details><small>风险等级：{{ selectedEntry.riskLevel }}</small></article>
      </section>
       <aside v-if="toc.length" class="toc"><p class="eyebrow">ON THIS PAGE</p><a v-for="entry in toc" :key="entry.anchor" :href="`#${entry.anchor}`">{{ entry.title }}</a></aside><section id="overview" class="content-stack">
        <div v-for="block in blocks" :key="block.id" class="content-block" :id="block.anchor || undefined">
          <h2 v-if="block.title">{{ block.title }}</h2>
           <pre v-if="block.kind === 'code' && item.type !== 'visual'" class="code-block"><code>{{ payload(block).code || payload(block).markdown || '' }}</code><button type="button" @click="copyCode(payload(block).code || '')">{{ copiedCode ? '已复制' : '复制' }}</button><span class="sr-only" aria-live="polite">{{ copiedCode ? '代码已复制' : '' }}</span></pre>
          <div v-else-if="block.kind === 'comparison'" class="comparison-grid"><figure v-for="side in ['beforeMediaId', 'afterMediaId']" :key="side"><template v-if="mediaById(payload(block)[side])"><img :src="mediaById(payload(block)[side]).url" :alt="side === 'beforeMediaId' ? 'Before' : 'After'" loading="lazy" @error="mediaFailed(mediaById(payload(block)[side]).id)" /></template><a v-else class="media-fallback" :href="item.resources?.[0]?.url || '#'">打开资源</a><figcaption>{{ side === 'beforeMediaId' ? 'Before' : 'After' }}</figcaption></figure></div>
          <div v-else-if="block.kind === 'imageGallery'" class="gallery-strip"><template v-for="mediaId in (payload(block).mediaIds || [])" :key="mediaId"><img v-if="mediaById(mediaId)" :src="mediaById(mediaId).url" :alt="mediaById(mediaId).alt || item.title" loading="lazy" @error="mediaFailed(mediaById(mediaId).id)" /></template></div>
          <iframe v-else-if="block.kind === 'embed'" :src="payload(block).url" :title="block.title || item.title" loading="lazy" sandbox="allow-scripts allow-same-origin" />
          <p v-else-if="payload(block).text || payload(block).markdown">{{ payload(block).text || payload(block).markdown }}</p>
          <div v-else-if="block.kind === 'timeline'" class="timeline"><p v-for="step in (payload(block).items || [])" :key="step.title"><b>{{ step.title }}</b> {{ step.description }}</p></div>
        </div>
      </section>
      <nav v-if="item.related?.length" class="related"><p class="eyebrow">继续浏览</p><NuxtLink v-for="next in item.related" :key="next.id" :to="`/portfolio/${next.slug}`">{{ next.title }} <span>↗</span></NuxtLink></nav>
      <div v-if="lightbox" class="lightbox" role="dialog" aria-modal="true" @click.self="lightbox = null"><button type="button" aria-label="关闭画廊" @click="lightbox = null">×</button><img :src="lightbox.url" :alt="lightbox.alt || item.title" /><p>{{ lightbox.caption }}</p></div>
    </article>
  </main>
</template>

<style scoped>
.detail-shell{min-height:100vh;background:#061115;color:#dce9e4;padding:38px clamp(20px,6vw,96px) 100px}.detail{max-width:1200px;margin:auto}.back{color:#91f1d3;text-decoration:none;font:11px/1.2 monospace;letter-spacing:.16em;text-transform:uppercase}.hero{display:grid;grid-template-columns:minmax(0,1fr) 240px;gap:48px;padding:92px 0 58px;border-bottom:1px solid rgba(145,241,211,.18)}.eyebrow{color:#91f1d3;font:11px monospace;letter-spacing:.18em;text-transform:uppercase}.hero h1{font-size:clamp(48px,9vw,120px);line-height:.94;letter-spacing:-.06em;margin:16px 0 26px}.lede{max-width:620px;color:#9db2ae;font-size:18px;line-height:1.7}.facts{display:flex;flex-direction:column;gap:14px;color:#91a5a0;font:12px monospace;padding-top:22px}.media-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px;margin:46px 0}.media-card{margin:0;background:#0d2023;border:1px solid rgba(145,241,211,.15)}.media-card:first-child{grid-column:span 2}.media-card img,.media-card video{display:block;width:100%;aspect-ratio:16/9;object-fit:cover;background:#08181b}.media-card figcaption{padding:12px;color:#8fa5a0;font-size:12px}.content-stack{max-width:820px;margin:50px 0}.content-block{padding:28px 0;border-top:1px solid rgba(145,241,211,.14)}.content-block h2{font-size:24px;margin:0 0 14px}.content-block p{color:#b8c9c5;line-height:1.9;white-space:pre-wrap}.code-block{position:relative;overflow:auto;padding:22px;background:#02090b;color:#91f1d3;border:1px solid rgba(145,241,211,.2);white-space:pre-wrap}.code-block button{position:absolute;top:10px;right:10px;background:transparent;color:#91f1d3;border:1px solid #91f1d3;padding:6px 10px}.tool-vault{margin:48px 0}.section-head{display:flex;justify-content:space-between;align-items:center}.section-head span{font:12px monospace;color:#8fa5a0}.prompt-entry{border-top:1px solid rgba(145,241,211,.18);padding:18px 0}.prompt-entry summary{cursor:pointer;display:flex;justify-content:space-between;gap:20px}.prompt-entry small{color:#8fa5a0}.prompt-entry a{display:inline-block;margin-top:12px;color:#91f1d3}.related{display:grid;gap:12px;max-width:560px}.related a{display:flex;justify-content:space-between;color:#dce9e4;text-decoration:none;border-bottom:1px solid rgba(145,241,211,.18);padding:14px 0}.empty{min-height:70vh;display:grid;place-content:center;gap:18px;text-align:center;color:#91f1d3;font:12px monospace}.empty a{color:#dce9e4}.skeleton{height:45vh;background:linear-gradient(90deg,#0b1c1f,#183032,#0b1c1f);animation:pulse 1.4s infinite}.skeleton.short{height:24px;width:40%;margin-top:20px}@keyframes pulse{50%{opacity:.5}}@media(max-width:760px){.hero{grid-template-columns:1fr;padding-top:58px}.facts{padding-top:0}.media-grid{grid-template-columns:1fr}.media-card:first-child{grid-column:auto}.hero h1{font-size:clamp(48px,17vw,86px)}.prompt-entry summary{display:block}.prompt-entry small{display:block;margin-top:8px}}
