gba(127,188,218,.2)}
@media(max-width:860px){.detail .hero{grid-template-columns:1fr;gap:24px;padding:42px 22px}.detail .content-stack,.detail .tool-vault{padding-inline:0}.detail .toc{position:static;float:none;width:auto;margin:24px 0}.detail .media-grid,.detail-visual .media-grid{grid-template-columns:1fr}.detail .media-card:first-child{grid-column:auto}.detail-visual .media-card:first-child img,.detail-visual .media-card:first-child video{aspect-ratio:16/9}.detail .hero h1{font-size:clamp(46px,12vw,86px)}}
.detail-visual .media-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.detail-visual .media-card:first-child{grid-column:1/-1}.detail-visual .media-card:not(:first-child) img,.detail-visual .media-card:not(:first-child) video{aspect-ratio:4/3}.detail-project .timeline{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;counter-reset:step}.detail-project .timeline p{position:relative;padding:48px 14px 14px;border-top:1px solid rgba(127,188,218,.34);color:#b7cad2}.detail-project .timeline p:before{counter-increment:step;content:counter(step,decimal-leading-zero);position:absolute;top:9px;left:0;color:#56d8f4;font:20px var(--font-mono)}.tool-side{display:flex;align-items:center;gap:16px;margin:0 0 18px;padding:14px 16px;border:1px solid rgba(127,188,218,.2);border-radius:8px;background:rgba(9,27,45,.56);color:#c7d8df}.tool-side a{color:#91adbc;text-decoration:none}.tool-side a.active,.tool-side a:hover,.tool-side a:focus-visible{color:#5dddf7}.tool-side strong{margin-right:auto;color:#edf8fb}
.resource-preview{display:grid;gap:0;margin:0 0 22px;padding:14px 16px;border:1px solid rgba(127,188,218,.2);border-radius:8px;background:rgba(5,19,32,.72)}.resource-preview strong{margin-bottom:8px;color:#edf8fb}.resource-preview a{display:flex;justify-content:space-between;padding:10px 0;border-top:1px solid rgba(127,188,218,.14);color:#58d8f3;text-decoration:none}.resource-preview a:hover,.resource-preview a:focus-visible{color:#e8fbff}.resource-preview b{font-weight:400}
.visual-info-band{display:grid;grid-template-columns:repeat(4,1fr);gap:0;margin:0 0 32px;padding:18px 22px;border:1px solid rgba(127,188,218,.24);border-radius:8px;background:linear-gradient(90deg,rgba(10,31,51,.9),rgba(5,18,31,.8))}.visual-info-band div{display:grid;gap:7px;padding:0 18px;border-right:1px solid rgba(127,188,218,.16)}.visual-info-band div:first-child{padding-left:0}.visual-info-band div:last-child{border-right:0}.visual-info-band span{color:#8eaab9;font:11px var(--font-mono)}.visual-info-band b{color:#e4f5fa;font-weight:500}@media(max-width:860px){.visual-info-band{grid-template-columns:repeat(2,1fr);gap:16px}.visual-info-band div:nth-child(2){border-right:0}.visual-info-band div:nth-child(3){padding-left:0}}
.hero-media{overflow:hidden;margin:26px 0 0;border:1px solid rgba(127,188,218,.25);border-radius:7px}.hero-media img{display:block;width:100%;max-height:280px;object-fit:cover}.detail-project .hero-media{max-width:720px}
